function report=capture_training_issue_018(app,phase)
assert(isa(app,'CamReplicaApp') && isvalid(app) && isgraphics(app.Figure));
assert(~app.Busy && ~app.SimulationMode && ~app.MapEditMode);
folder=fullfile(fileparts(fileparts(mfilename('fullpath'))),'outputs','ui_training_feedback_20261031','parent_independent');
if ~isfolder(folder), mkdir(folder); end
file=fullfile(folder,[phase '.json']); backupFile=fullfile(folder,[phase '.mat']);
assert(~isfile(file) && ~isfile(backupFile));
backup=app.snapshotModelSwitchState(); extra=cam_app_ui_value_snapshot(app);
save(backupFile,'backup','extra','-v7'); saved=load(backupFile);
assert(isequaln(saved.backup,backup) && isequaln(saved.extra,extra));
report=struct('phase',phase,'actualControlCount',size(app.Project.nodes,1),'trainingInputs',[app.TrainingFields.Value], ...
    'trainingDirty',app.TrainingDirty,'model',app.TrainingModel.Value,'algorithm',app.AlgorithmSelector.Value, ...
    'dynamicWeightsEnabled',app.DynamicWeightsEnabled.Value,'optimizeEnabled',char(app.Buttons(5).Enable), ...
    'optimizeTooltip',app.Buttons(5).Tooltip,'calculateEnabled',char(app.Buttons(4).Enable), ...
    'status',app.Status.Text,'trainingInfo',app.TrainingInfo.Text,'methodSummary',app.MethodSummary.Text, ...
    'log',{app.FullLog},'backupFile',backupFile,'stateUnchanged',isequaln(backup,app.snapshotModelSwitchState()));
if isfield(app.Project,'routeMapping'), report.mapping=app.Project.routeMapping; end
fid=fopen(file,'w','n','UTF-8'); assert(fid>=0); cleaner=onCleanup(@()fclose(fid));
fprintf(fid,'%s',jsonencode(report,PrettyPrint=true));
disp('TRAINING_ISSUE_CAPTURED_READ_ONLY');
end

function report=refresh_training_feedback_018(app)
% Parent-side presentation refresh only; never apply or compute user input.
folder=fullfile(fileparts(fileparts(mfilename('fullpath'))),'outputs','ui_training_feedback_20261031','parent_independent');
file=fullfile(folder,'verification.json'); assert(~isfile(file));
capture_training_issue_018(app,'before_refresh');
before=app.snapshotModelSwitchState();
app.refreshControls();
after=app.snapshotModelSwitchState();
capture_training_issue_018(app,'after_refresh');
assert(isequaln(before,after),'cam:LiveRefreshStateChanged','Display refresh changed saved model/input state.');
conflict=before.inputs.DynamicWeightsEnabled && ismember(before.inputs.AlgorithmSelector, ...
    {'feasibility-four-direction-v1','relay-sqp-v1','multistart-relay-sqp-v1'});
if conflict
    assert(contains(app.MethodSummary.Text,'动态权重') && contains(app.MethodSummary.Text,'权重'), ...
        'cam:LiveFeedback','Current dynamic-weight conflict must be visible.');
    assert(strcmp(app.Buttons(5).Enable,'off'));
end
assert(isequal(before.inputs.DynamicWeightsEnabled,app.DynamicWeightsEnabled.Value));
assert(contains(app.TrainingApplyButton.Text,'保形') && contains(app.ForceModelSwitchButton.Text,'强制调整'));
initial=load(fullfile(folder,'before.mat'),'backup');
report=struct('immediateStatePreserved',isequaln(before,after),'initialCaptureStillMatches',isequaln(initial.backup,before), ...
    'model',app.TrainingModel.Value,'algorithm',app.AlgorithmSelector.Value, ...
    'dynamicWeightsPreserved',app.DynamicWeightsEnabled.Value,'optimizeEnable',char(app.Buttons(5).Enable), ...
    'visibleReason',app.MethodSummary.Text,'preserveAction',app.TrainingApplyButton.Text,'reshapeAction',app.ForceModelSwitchButton.Text, ...
    'controlCount',size(app.Project.nodes,1),'pendingFields',[app.TrainingFields.Value], ...
    'scope','Current window refreshed only; no apply, calculation, mapping, optimize, import, export, reset, or dynamic-weight modification.');
fid=fopen(file,'w','n','UTF-8'); assert(fid>=0); cleaner=onCleanup(@()fclose(fid)); fprintf(fid,'%s',jsonencode(report,PrettyPrint=true));
disp('TRAINING_FEEDBACK_LIVE_REFRESH_PASS');
end

function report=compare_training_captures_018()
folder=fullfile(fileparts(fileparts(mfilename('fullpath'))),'outputs','ui_training_feedback_20261031','parent_independent');
file=fullfile(folder,'initial_comparison.json'); assert(~isfile(file));
first=load(fullfile(folder,'before.mat'),'backup'); next=load(fullfile(folder,'before_refresh.mat'),'backup');
a=first.backup; b=next.backup; changed={}; names=fieldnames(a);
for k=1:numel(names), if ~isequaln(a.(names{k}),b.(names{k})), changed{end+1}=names{k}; end, end
stateChanged={}; names=fieldnames(a.state);
for k=1:numel(names), if ~isequaln(a.state.(names{k}),b.state.(names{k})), stateChanged{end+1}=names{k}; end, end
inputChanged={}; names=fieldnames(a.inputs);
for k=1:numel(names), if ~isequaln(a.inputs.(names{k}),b.inputs.(names{k})), inputChanged{end+1}=names{k}; end, end
report=struct('initialToBeforeRefreshChangedFields',{changed},'stateChangedFields',{stateChanged}, ...
    'inputChangedFields',{inputChanged},'initialAxesLimits',a.axesLimits,'beforeRefreshAxesLimits',b.axesLimits, ...
    'scope','Read-only comparison of two already saved snapshots; separates changes before refresh from the exact immediate before/after preservation check.');
fid=fopen(file,'w','n','UTF-8'); assert(fid>=0); cleaner=onCleanup(@()fclose(fid)); fprintf(fid,'%s',jsonencode(report,PrettyPrint=true));
disp('TRAINING_CAPTURE_COMPARISON_SAVED');
end
